import React, {Component} from 'react';
import StravaChart from "../../containers/StravaChart";
import { Table, Radio, Space, Typography, Empty, Card } from 'antd';
import { UserOutlined, DashboardOutlined, ThunderboltOutlined, TrophyOutlined } from '@ant-design/icons';
import { Link } from "react-router-dom";
import { isMobile } from 'react-device-detect';

const { Title } = Typography;

class StravaTable extends Component {
    componentDidMount() {
        this.checkUrlForUser();
    }

    componentDidUpdate(prevProps) {
        if (this.props.location.pathname !== prevProps.location.pathname) {
            this.checkUrlForUser();
        }
    }

    checkUrlForUser() {
        const { userNames } = this.props;
        const currentURL = window.location.href;
        const urlArr = currentURL.split('/');
        const nameInUrl = urlArr[urlArr.length - 1];
        if (userNames.includes(nameInUrl)) {
            this.singleSetUser(nameInUrl);
        }
    }

    singleSetUser(user) {
        const { currentUser, setCurrentUser } = this.props;
        if (user !== currentUser) {
            setCurrentUser(user);
        }
    }

    setUser(selectedUser) {
        const { currentUser, setCurrentUser } = this.props;
        const athlete = currentUser === selectedUser ? "" : selectedUser;
        setCurrentUser(athlete);
    }

    getSummaryColumns() {
        const { activityUnit } = this.props;
        const unit = activityUnit === "km" ? "km" : "miles";

        return [
            {
                title: <span><UserOutlined />{isMobile ? "" : " Name"}</span>,
                dataIndex: 'name',
                key: 'name',
                render: (text) => <Link to={`/home/${text}`} style={{ fontWeight: 500 }}>{text}</Link>,
                sorter: (a, b) => a.name.localeCompare(b.name),
                fixed: isMobile ? 'left' : false,
            },
            {
                title: <span><ThunderboltOutlined />{isMobile ? "" : " Runs"}</span>,
                dataIndex: 'runQuantity',
                key: 'runQuantity',
                sorter: (a, b) => a.runQuantity - b.runQuantity,
                align: 'center',
                responsive: ['sm'],
            },
            {
                title: isMobile ? "Run" : `Run Dist (${unit})`,
                key: 'runDistance',
                render: (_, record) => activityUnit === "km" ? record.runDistance : record.runDistanceMile,
                sorter: (a, b) => {
                    const valA = activityUnit === "km" ? a.runDistance : a.runDistanceMile;
                    const valB = activityUnit === "km" ? b.runDistance : b.runDistanceMile;
                    return Number(valA) - Number(valB);
                },
                align: 'right',
            },
            {
                title: <span><DashboardOutlined />{isMobile ? "" : " Cycles"}</span>,
                dataIndex: 'bikeQuantity',
                key: 'bikeQuantity',
                sorter: (a, b) => a.bikeQuantity - b.bikeQuantity,
                align: 'center',
                responsive: ['sm'],
            },
            {
                title: isMobile ? "Cycle" : `Cycle Dist (${unit})`,
                key: 'bikeDistance',
                render: (_, record) => activityUnit === "km" ? record.bikeDistance : record.bikeDistanceMile,
                sorter: (a, b) => {
                    const valA = activityUnit === "km" ? a.bikeDistance : a.bikeDistanceMile;
                    const valB = activityUnit === "km" ? b.bikeDistance : b.bikeDistanceMile;
                    return Number(valA) - Number(valB);
                },
                align: 'right',
            },
            {
                title: <span><TrophyOutlined />{isMobile ? "" : " Swims"}</span>,
                dataIndex: 'swimQuantity',
                key: 'swimQuantity',
                sorter: (a, b) => a.swimQuantity - b.swimQuantity,
                align: 'center',
                responsive: ['sm'],
            },
            {
                title: isMobile ? "Swim" : `Swim Dist (${unit})`,
                key: 'swimDistance',
                render: (_, record) => activityUnit === "km" ? record.swimDistance : record.swimDistanceMile,
                sorter: (a, b) => {
                    const valA = activityUnit === "km" ? a.swimDistance : a.swimDistanceMile;
                    const valB = activityUnit === "km" ? b.swimDistance : b.swimDistanceMile;
                    return Number(valA) - Number(valB);
                },
                align: 'right',
            },
        ];
    }

    getDetailedColumns() {
        const { currentActivityType, activityUnit } = this.props;
        const singleUnit = activityUnit === "km" ? "km" : "mile";
        const speedUnit = activityUnit === "km" ? "k" : "m";
        const swimSpeedUnit = activityUnit === "km" ? "100m" : "100y";

        const cols = [
            {
                title: 'Date',
                dataIndex: 'date',
                key: 'date',
                sorter: (a, b) => {
                    const parseDate = (d) => {
                        const parts = d.split('/');
                        return new Date(2000 + parseInt(parts[2]), parts[1] - 1, parts[0]);
                    };
                    return parseDate(a.date) - parseDate(b.date);
                },
                defaultSortOrder: 'descend',
                fixed: isMobile ? 'left' : false,
            },
            {
                title: 'Activity',
                dataIndex: 'activity',
                key: 'activity',
                sorter: (a, b) => a.activity.localeCompare(b.activity),
                responsive: ['sm'],
            },
            {
                title: isMobile ? 'Dist' : `Distance (${activityUnit === "km" && currentActivityType === "swim" ? "m" : singleUnit})`,
                key: 'distance',
                render: (_, record) => {
                    if (activityUnit === "km") {
                        return record.distance + (currentActivityType === "swim" ? "m" : " km");
                    }
                    return record.distanceMile + (isMobile ? "m" : " miles");
                },
                sorter: (a, b) => {
                    const valA = activityUnit === "km" ? a.distance : a.distanceMile;
                    const valB = activityUnit === "km" ? b.distance : b.distanceMile;
                    return Number(valA) - Number(valB);
                },
            },
            {
                title: isMobile ? 'Speed' : 'Average Speed',
                key: 'averageSpeed',
                render: (_, record) => {
                    const speed = activityUnit === "km" ? record.averageSpeed : record.averageSpeedMile;
                    const unitStr = currentActivityType === "cycle" ? 
                                    speedUnit + "ph" : 
                                    "min/" + (currentActivityType === "run" ? singleUnit : swimSpeedUnit);
                    return `${speed} ${unitStr}`;
                },
                sorter: (a, b) => {
                    const valA = activityUnit === "km" ? a.averageSpeed : a.averageSpeedMile;
                    const valB = activityUnit === "km" ? b.averageSpeed : b.averageSpeedMile;
                    return Number(valA) - Number(valB);
                },
            },
            {
                title: isMobile ? 'Time' : 'Time (min)',
                dataIndex: 'movingTime',
                key: 'movingTime',
                sorter: (a, b) => Number(a.movingTime) - Number(b.movingTime),
                responsive: ['sm'],
            },
        ];

        if (currentActivityType !== "swim") {
            cols.push({
                title: isMobile ? 'Elev' : 'Elevation (m)',
                dataIndex: 'elevationGain',
                key: 'elevationGain',
                sorter: (a, b) => Number(a.elevationGain) - Number(b.elevationGain),
                responsive: ['md'],
            });
        }

        return cols;
    }

    render() {
        const { 
            allRows, 
            activityUnit, 
            setActivityUnit, 
            currentUser, 
            currentActivityType, 
            setCurrentActivityType,
            currentUserCurrentActivityData,
            isDarkMode,
            loading
        } = this.props;

        return (
            <Space direction="vertical" size="large" style={{ width: '100%' }}>
                <div style={{ 
                    display: 'flex', 
                    flexDirection: isMobile ? 'column' : 'row',
                    justifyContent: 'space-between', 
                    alignItems: isMobile ? 'flex-start' : 'center', 
                    marginBottom: '10px',
                    gap: '10px'
                }}>
                    <Title level={4} style={{ margin: 0 }}>Activity Overview</Title>
                    <Radio.Group value={activityUnit} onChange={(e) => setActivityUnit(e.target.value)} buttonStyle="solid" size={isMobile ? "small" : "middle"}>
                        <Radio.Button value="km">Metric (km)</Radio.Button>
                        <Radio.Button value="miles">Imperial (miles)</Radio.Button>
                    </Radio.Group>
                </div>

                <Table 
                    columns={this.getSummaryColumns()} 
                    dataSource={allRows} 
                    rowKey="name"
                    pagination={false}
                    onRow={(record) => ({
                        onClick: () => this.setUser(record.name),
                        style: { cursor: 'pointer' }
                    })}
                    rowClassName={(record) => record.name === currentUser ? 'ant-table-row-selected' : ''}
                    size={isMobile ? "small" : "middle"}
                    bordered
                    scroll={{ x: isMobile ? 'max-content' : undefined }}
                    loading={loading}
                />

                {currentUser ? (
                    <Card style={{ marginTop: isMobile ? '10px' : '20px', border: '1px solid #f0f0f0' }} bodyStyle={{ padding: isMobile ? '12px' : '24px' }}>
                        <Space direction="vertical" size="middle" style={{ width: '100%' }}>
                            <div style={{ 
                                display: 'flex', 
                                flexDirection: isMobile ? 'column' : 'row',
                                justifyContent: 'space-between', 
                                alignItems: isMobile ? 'flex-start' : 'center',
                                gap: '10px'
                            }}>
                                <Title level={4} style={{ margin: 0 }}>{currentUser}'s Detailed Stats</Title>
                                <Radio.Group value={currentActivityType} onChange={(e) => setCurrentActivityType(e.target.value)} buttonStyle="solid" size={isMobile ? "small" : "middle"}>
                                    <Radio.Button value="run">Run</Radio.Button>
                                    <Radio.Button value="cycle">Cycle</Radio.Button>
                                    <Radio.Button value="swim">Swim</Radio.Button>
                                </Radio.Group>
                            </div>

                            {currentUserCurrentActivityData && currentUserCurrentActivityData.length > 0 ? (
                                <>
                                    <div style={{ 
                                        background: isDarkMode ? '#1f1f1f' : '#fafafa', 
                                        padding: isMobile ? '10px' : '20px', 
                                        borderRadius: '8px', 
                                        marginBottom: '20px' 
                                    }}>
                                        <StravaChart isDarkMode={isDarkMode} />
                                    </div>
                                    <Table 
                                        columns={this.getDetailedColumns()} 
                                        dataSource={currentUserCurrentActivityData} 
                                        rowKey="startDate"
                                        pagination={false}
                                        size="small"
                                        scroll={{ x: isMobile ? 'max-content' : undefined }}
                                    />
                                </>
                            ) : (
                                <Empty description={<span>{currentUser} has no {currentActivityType} data available.</span>} />
                            )}
                        </Space>
                    </Card>
                ) : null}
            </Space>
        );
    }
}

export default StravaTable;

